// Checks the API request and turns the guest's purchases, the price list, and their sign-ins into a profile
// for the Graphic Designer Agent: how often they come, what they order, what it costs today, and whether
// they have been signing in without ordering.
const s = $('Settings').first().json;
const body = $('Graphic Request').first().json.body ?? {};
const tz = s.timezone;
const now = $now.setZone(tz);
const errors = [];

const text = (v, max = 200) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const num = (v) => {
  const n = typeof v === 'string' ? Number(v.replace(/[^0-9.-]/g, '')) : Number(v);
  return v === null || v === undefined || v === '' || !Number.isFinite(n) ? null : n;
};
const when = (v) => {
  const d = typeof v === 'number' ? DateTime.fromMillis(v) : DateTime.fromISO(String(v ?? ''), { setZone: true });
  return d.isValid ? d.setZone(tz) : null;
};
const key = (v) => text(v).toLowerCase();
const money = (n) => new Intl.NumberFormat(s.locale || 'en-US', {
  style: 'currency', currency: s.currency || 'USD', minimumFractionDigits: n % 1 ? 2 : 0,
}).format(n);
const daysAgo = (d) => Math.max(0, Math.floor(now.diff(d, 'days').days));

const guest = body.guest && typeof body.guest === 'object' ? body.guest : {};
if (!Array.isArray(body.purchases)) errors.push('purchases must be an array (send [] for a guest who has not ordered yet)');
if (!Array.isArray(body.prices) || !body.prices.length) errors.push('prices must be a non-empty array of menu items, each with name and price');
if (body.sign_ins !== undefined && !Array.isArray(body.sign_ins)) errors.push('sign_ins must be an array');

// ---------- Price list (only items that are available today)
const menu = [];
(Array.isArray(body.prices) ? body.prices : []).slice(0, 500).forEach((p, i) => {
  const name = text(p?.name, 80);
  const price = num(p?.price);
  if (!name || price === null || price < 0) {
    errors.push(`prices[${i}] needs a name and a price`);
    return;
  }
  if (p.available === false || menu.some((m) => key(m.name) === key(name))) return;
  menu.push({ name, price, category: text(p.category, 60), description: text(p.description, 160), is_new: p.is_new === true });
});
const onMenu = new Map(menu.map((m) => [key(m.name), m]));

// ---------- Purchases
const visits = [];
(Array.isArray(body.purchases) ? body.purchases : []).slice(0, 1000).forEach((o, i) => {
  const d = when(o?.date ?? o?.purchased_at ?? o?.created_at);
  if (!d) {
    errors.push(`purchases[${i}] needs a date in ISO 8601 format`);
    return;
  }
  const items = (Array.isArray(o.items) ? o.items : [])
    .map((li) => ({ name: text(li?.name, 80), quantity: num(li?.quantity) ?? 1, price: num(li?.price) }))
    .filter((li) => li.name);
  const total = num(o.total) ?? items.reduce((sum, li) => sum + (li.price ?? 0) * li.quantity, 0);
  visits.push({ d, items, total, type: text(o.order_type ?? o.type, 30).toLowerCase() || 'unknown' });
});
visits.sort((a, b) => a.d - b.d);

// ---------- Sign-ins
const signIns = (Array.isArray(body.sign_ins) ? body.sign_ins : []).slice(0, 2000)
  .map((x) => ({ d: when(typeof x === 'object' && x !== null ? x.date ?? x.at ?? x.signed_in_at : x), channel: text(x?.channel, 30).toLowerCase() || 'unknown' }))
  .filter((x) => x.d)
  .sort((a, b) => a.d - b.d);

if (errors.length) {
  return [{ json: { valid: false, errors: errors.slice(0, 10) } }];
}

// ---------- Visit patterns
const daypart = (h) => (h >= 5 && h < 11 ? 'breakfast' : h >= 11 && h < 16 ? 'lunch' : h >= 16 && h < 22 ? 'dinner' : 'late night');
const top = (values, n = 1) => {
  const counts = new Map();
  values.forEach((v) => counts.set(v, (counts.get(v) ?? 0) + 1));
  return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, n);
};
const days = [...new Set(visits.map((v) => v.d.toISODate()))];
const gaps = days.slice(1).map((d, i) => DateTime.fromISO(d).diff(DateTime.fromISO(days[i]), 'days').days).sort((a, b) => a - b);
const medianGap = gaps.length ? Math.round(gaps[Math.floor((gaps.length - 1) / 2)]) : null;
const last = visits.at(-1) ?? null;
const sinceLast = last ? daysAgo(last.d) : null;
const totalSpent = visits.reduce((sum, v) => sum + v.total, 0);

// Favorite items, with today's price from the price list
const dishes = new Map();
for (const v of visits) {
  for (const li of v.items) {
    const k = key(li.name);
    const dish = dishes.get(k) ?? { name: li.name, visits: 0, quantity: 0, last_paid: null };
    dish.visits += 1;
    dish.quantity += li.quantity;
    if (li.price !== null) dish.last_paid = li.price;
    dishes.set(k, dish);
  }
}
const favorites = [...dishes.values()].sort((a, b) => b.visits - a.visits || b.quantity - a.quantity).slice(0, 5).map((dish) => {
  const item = onMenu.get(key(dish.name));
  return { ...dish, name: item?.name ?? dish.name, on_menu: Boolean(item), current_price: item?.price ?? null };
});

// Sign-in patterns
const lastSignIn = signIns.at(-1) ?? null;
const signInsSincePurchase = last ? signIns.filter((x) => x.d > last.d).length : signIns.length;
const within = (n) => signIns.filter((x) => daysAgo(x.d) <= n).length;

// Segment
const lapsedAfter = Math.max(Number(s.lapsed_after_days) || 45, medianGap ? medianGap * 2 : 0);
let segment;
if (!visits.length) segment = signIns.length ? 'signed_up_never_ordered' : 'new_guest';
else if (visits.length === 1 && sinceLast <= 30) segment = 'first_visit_recent';
else if (sinceLast >= lapsedAfter) segment = signInsSincePurchase >= 2 ? 'lapsed_but_browsing' : 'lapsed';
else if (visits.length >= 4) segment = 'regular';
else segment = 'occasional';
const SEGMENTS = {
  new_guest: 'No orders and no sign-ins yet.',
  signed_up_never_ordered: 'Has an account and signs in, but has never ordered.',
  first_visit_recent: 'Ordered once, in the last 30 days.',
  lapsed: `Has not ordered in ${sinceLast} days, longer than usual, and is not signing in either.`,
  lapsed_but_browsing: `Has not ordered in ${sinceLast} days, but has signed in ${signInsSincePurchase} times since: interested, not buying.`,
  regular: 'Orders often and recently.',
  occasional: 'Orders now and then, and is not overdue.',
};

// Menu items to suggest: not tried yet, in the categories they order from, then new items
const tried = new Set(dishes.keys());
const favCategories = new Set(favorites.map((f) => onMenu.get(key(f.name))?.category).filter(Boolean));
const suggestions = menu
  .filter((m) => !tried.has(key(m.name)))
  .sort((a, b) => Number(favCategories.has(b.category)) - Number(favCategories.has(a.category)) || Number(b.is_new) - Number(a.is_new))
  .slice(0, 8);

// Price list for the prompt: favorites and suggestions first, then the rest, up to 60 items
const shown = [];
for (const m of [...favorites.map((f) => onMenu.get(key(f.name))).filter(Boolean), ...suggestions, ...menu.filter((x) => x.is_new), ...menu]) {
  if (!shown.includes(m) && shown.length < 60) shown.push(m);
}

const campaign = body.campaign && typeof body.campaign === 'object' ? body.campaign : {};
const firstName = text(guest.first_name, 40);
const offer = text(campaign.offer, 80);
const size = ['landscape', 'square', 'portrait'].includes(campaign.size) ? campaign.size : 'landscape';

const prompt = [
  'GUEST',
  `First name: ${firstName || 'unknown. Do not use a name.'}`,
  `Segment: ${segment}. ${SEGMENTS[segment]}`,
  '',
  'PURCHASES',
  visits.length
    ? [
      `Orders: ${visits.length} (first ${visits[0].d.toISODate()}, last ${last.d.toISODate()}, ${sinceLast} days ago)`,
      `Usually orders ${top(visits.map((v) => daypart(v.d.hour)))[0][0]} on ${top(visits.map((v) => v.d.toFormat('cccc')), 2).map((x) => x[0]).join(' and ')}, mostly ${top(visits.map((v) => v.type))[0][0]}.`,
      medianGap ? `Usually orders again every ${medianGap} days.` : 'Not enough orders to know how often they come back.',
      `Average order: ${money(totalSpent / visits.length)}.`,
      'Favorite items (name | orders that included it | price today | last price paid):',
      ...favorites.map((f) => `- ${f.name} | ${f.visits} | ${f.on_menu ? money(f.current_price) : 'no longer on the menu'} | ${f.last_paid !== null ? money(f.last_paid) : 'unknown'}`),
      'Last 3 orders:',
      ...visits.slice(-3).reverse().map((v) => `- ${v.d.toFormat('ccc, LLL d')} ${daypart(v.d.hour)}, ${v.type}: ${v.items.map((li) => li.name).join(', ') || 'no items'} (${money(v.total)})`),
    ].join('\n')
    : 'No orders yet.',
  '',
  'SIGN-INS',
  signIns.length
    ? `${within(30)} in the last 30 days, ${within(90)} in the last 90. Last sign-in ${lastSignIn.d.toISODate()} (${daysAgo(lastSignIn.d)} days ago). ${signInsSincePurchase} since their last order. Channels: ${top(signIns.map((x) => x.channel), 3).map(([c, n]) => `${c} (${n})`).join(', ')}.`
    : 'No sign-ins.',
  '',
  'ITEMS THEY HAVE NOT TRIED (good suggestions)',
  suggestions.map((m) => `- ${m.name}${m.is_new ? ' (new)' : ''}`).join('\n') || 'none',
  '',
  'PRICE LIST (name | price | category | new). Only these items can appear in the graphic.',
  shown.map((m) => `- ${m.name} | ${money(m.price)} | ${m.category || '-'}${m.is_new ? ' | new' : ''}`).join('\n'),
  '',
  'CAMPAIGN',
  `Goal: ${text(campaign.goal, 300) || 'your choice: the message most likely to get this guest to order again soon'}`,
  `Offer: ${offer || 'none. Do not show or mention any discount or deal.'}`,
  `Graphic shape: ${size}`,
  `Today: ${now.toFormat('cccc, LLLL d, yyyy')}`,
].join('\n');

return [{
  json: {
    valid: true,
    guest_id: text(guest.id, 80),
    first_name: firstName,
    segment,
    offer,
    size,
    menu,
    favorites,
    stats: {
      orders: visits.length,
      days_since_last_order: sinceLast,
      usual_days_between_orders: medianGap,
      sign_ins_last_30_days: within(30),
      sign_ins_since_last_order: signInsSincePurchase,
    },
    prompt,
  },
}];

