// Checks the agent's design brief against the price list and writes the image prompt.
// Prices always come from the price list, never from the AI, and every piece of text is listed
// so the Text Check can confirm it after the image is made.
const s = $('Settings').first().json;
const r = $('Read Request').first().json;
const b = $json.output ?? {};

// Plain text for the image: double quotes would break the quoted text list in the prompt
const clean = (v, max) => String(v ?? '').replace(/[“”"]/g, "'").replace(/\s+/g, ' ').trim().slice(0, max);
const words = (v) => String(v).toLowerCase().match(/[a-z0-9]+/g) ?? [];
const money = (n) => new Intl.NumberFormat(s.locale || 'en-US', {
  style: 'currency', currency: s.currency || 'USD', minimumFractionDigits: n % 1 ? 2 : 0,
}).format(n);
const onMenu = new Map(r.menu.map((m) => [m.name.toLowerCase(), m]));

// Featured items must be on the price list. A shorter label may only use words from the menu name.
const items = [];
for (const it of Array.isArray(b.featured_items) ? b.featured_items : []) {
  const m = onMenu.get(String(it?.name ?? '').trim().toLowerCase());
  if (!m || items.some((x) => x.name === m.name)) continue;
  const menuWords = new Set(words(m.name));
  let label = clean(it.label, 30);
  if (!label || !words(label).length || !words(label).every((w) => menuWords.has(w))) label = m.name;
  items.push({ name: m.name, label, price: m.price, price_text: money(m.price) });
  if (items.length === 3) break;
}
if (!items.length) {
  const fallback = r.favorites.map((f) => onMenu.get(f.name.toLowerCase())).find(Boolean) ?? r.menu[0];
  items.push({ name: fallback.name, label: fallback.name, price: fallback.price, price_text: money(fallback.price) });
}

const showPrices = b.show_prices !== false;
const headline = clean(b.headline, 40) || clean(`${r.first_name ? `${r.first_name}, ` : ''}we saved you a seat`, 40);
const subline = clean(b.subline, 70);
const shorten = (v, max) => {
  const t = clean(v, 500);
  return t.length <= max ? t : t.slice(0, max + 1).replace(/\s+\S*$/, '');
};
const offerBadge = r.offer ? clean(b.offer_badge, 32) || shorten(r.offer, 32) : '';
const cta = clean(b.cta_text, 22) || 'Order now';

// Every piece of text, in reading order
const expected = [{ role: 'headline', text: headline }];
if (subline) expected.push({ role: 'subline', text: subline });
for (const it of items) {
  expected.push({ role: 'item name', text: it.label });
  if (showPrices) expected.push({ role: `price of ${it.label}`, text: it.price_text });
}
if (offerBadge) expected.push({ role: 'offer badge', text: offerBadge });
expected.push({ role: 'button', text: cta });

const describe = (e) => ({
  headline: `Headline, the largest text: "${e.text}"`,
  subline: `Subline, smaller, under the headline: "${e.text}"`,
  'item name': `Item name: "${e.text}"`,
  'offer badge': `Offer badge, in a small ribbon or tag: "${e.text}"`,
  button: `Button text, on a solid rounded button: "${e.text}"`,
}[e.role] ?? `Price, right next to its item: "${e.text}"`);

const SIZES = { landscape: '1536x1024', square: '1024x1024', portrait: '1024x1536' };
const imagePrompt = [
  `A polished ${r.size} email header graphic for ${s.restaurant_name}, a ${s.cuisine} restaurant.`,
  `Scene: ${clean(b.visual_scene, 700) || `An appetizing, close-up photo of ${items[0].name}.`}`,
  `Layout: ${clean(b.layout, 400) || 'The food on one side, the text on a clean solid panel on the other side.'}`,
  `Style: ${s.brand_style}`,
  `Colors: ${s.brand_colors}`,
  `Typography: ${s.font_style}`,
  '',
  'TEXT IN THE IMAGE',
  'Show only the text below. Show each piece once, spelled exactly as written, with the same capitalization, numbers, and punctuation:',
  ...expected.map((e, i) => `${i + 1}. ${describe(e)}`),
  '',
  'RULES',
  '- No other words, letters, numbers, prices, logos, signs, menus, labels, or watermarks anywhere, including on plates, glasses, or anything else in the scene.',
  '- Each price sits right next to its item, exactly as written.',
  '- All text is large, high-contrast, and well inside the edges, with at least a 6% margin on every side, so nothing is cut off on a phone.',
].join('\n');

const checkPrompt = [
  'This email graphic should show exactly this text, and nothing else:',
  ...expected.map((e, i) => `${i + 1}. ${e.role}: "${e.text}"`),
  '',
  'Read every piece of text in the image exactly as it appears, letter by letter. Then report any expected text that is missing or',
  'spelled differently, any extra text (including small or garbled text on objects in the scene), any text cut off at an edge, and any text too hard to read.',
].join('\n');

return [{
  json: {
    image_prompt: imagePrompt,
    base_prompt: imagePrompt,
    size: SIZES[r.size],
    check_prompt: checkPrompt,
    expected,
    items,
    show_prices: showPrices,
    brief: {
      angle: clean(b.angle, 40),
      reasoning: clean(b.reasoning, 400),
      headline,
      email_subject: clean(b.email_subject, 80),
      preview_text: clean(b.preview_text, 120),
      alt_text: clean(b.alt_text, 200) || `${headline}. ${items.map((it) => it.label).join(', ')}.`,
    },
  },
}];

