// Compares the text the vision model read in the image with the text that should be there.
// Passed: returns the image. Problems: makes the image again with the problems called out,
// up to max_attempts. Still wrong after that: an error, or the image with a warning (Settings: on_failed_check).
const s = $('Settings').first().json;
const r = $('Read Request').first().json;
const built = $('Build Image Prompt').first().json;
const image = $('Generate Graphic').first();
const attempt = $runIndex + 1;
const maxAttempts = Math.min(5, Math.max(1, Number(s.max_attempts) || 3));
const check = $json.output ?? null;

// Case, quotes, and punctuation don't count; letters, numbers, and prices must match exactly
const norm = (v) => String(v ?? '').toLowerCase()
  .replace(/[‘’`]/g, "'")
  .replace(/(?<!\d)[.,]|[.,](?!\d)/g, ' ')
  .replace(/[^\p{L}\p{N}$€£¥.,%' ]+/gu, ' ')
  .replace(/\s+/g, ' ').trim();
const symbol = new Intl.NumberFormat(s.locale || 'en-US', { style: 'currency', currency: s.currency || 'USD' })
  .format(1).replace(/[\d.,\s ]/g, '');
const escape = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const prices = (v) => [...String(v).matchAll(new RegExp(`${escape(symbol)}\\s?(\\d{1,5}(?:[.,]\\d{1,2})?)`, 'g'))]
  .map((m) => Number(m[1].replace(',', '.')));

const problems = [];
if (!check || !Array.isArray(check.text_found)) {
  problems.push(`The text check could not read the image: ${String($json.error?.message ?? $json.error ?? 'no answer').slice(0, 200)}`);
} else {
  const found = check.text_found.map(String);
  const all = norm(found.join(' | '));
  for (const e of built.expected) {
    if (!all.includes(norm(e.text))) problems.push(`The ${e.role} should read "${e.text}" but is missing or spelled differently.`);
  }
  const allowed = built.show_prices ? built.items.map((it) => it.price) : [];
  for (const n of prices(found.join(' '))) {
    if (!allowed.some((p) => Math.abs(p - n) < 0.005)) problems.push(`The image shows a price that should not be there: ${symbol}${n}.`);
  }
  for (const issue of Array.isArray(check.issues) ? check.issues : []) {
    if (issue?.text) problems.push(`${String(issue.type ?? 'issue').replace(/_/g, ' ')}: ${String(issue.text).slice(0, 200)}`);
  }
}
const unique = [...new Set(problems)].slice(0, 8);

const headers = {
  subject: encodeURIComponent(built.brief.email_subject),
  preview: encodeURIComponent(built.brief.preview_text),
  alt: encodeURIComponent(built.brief.alt_text),
  headline: encodeURIComponent(built.brief.headline),
  file: `email-graphic-${String(r.guest_id || 'guest').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 40) || 'guest'}.png`,
};

if (!unique.length || (attempt >= maxAttempts && s.on_failed_check === 'return_image')) {
  return [{
    json: {
      status: unique.length ? 'unverified' : 'passed',
      send_image: true,
      attempts: attempt,
      problems: unique,
      headers,
      segment: r.segment,
      angle: built.brief.angle,
    },
    binary: image.binary,
  }];
}

if (attempt < maxAttempts) {
  return [{
    json: {
      status: 'retry',
      send_image: false,
      attempts: attempt,
      problems: unique,
      size: built.size,
      image_prompt: `${built.base_prompt}\n\nIMPORTANT: An earlier version of this graphic had these text problems. Fix every one:\n${unique.map((p) => `- ${p}`).join('\n')}\nUse fewer, larger letters, and spell every word and price exactly as listed.`,
    },
  }];
}

return [{
  json: {
    status: 'failed',
    send_image: false,
    attempts: attempt,
    problems: unique,
    error: `The text in the graphic could not be verified after ${attempt} attempts.`,
  },
}];
